        vm.assume(admin != address(0) && manager != address(0) && admin != manager);
        bytes32 DEFAULT_ADMIN_ROLE = 0x00;
        bytes32 MANAGER = keccak256("MANAGER");
        vm.startPrank(admin);
        c.initialize(admin);
        vm.stopPrank();
        vm.prank(admin);
        c.grantRole(DEFAULT_ADMIN_ROLE, admin);
        vm.prank(admin);
        c.grantRole(MANAGER, manager);
        bool beforePause = c.paused();
        vm.prank(manager);
        c.pause();
        bool afterPause = c.paused();
