contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize the contract so it's in a working state
        c.initialize(address(this));

        // Grant MANAGER role to this test contract so we can call pause()
        // The DEFAULT_ADMIN_ROLE is 0x00, which is held by this test contract (deployer)
        // We need to set up the LRTConfig to support role checks.
        // Since c's lrtConfig is set to address(this) during initialize,
        // and onlyLRTManager checks hasRole(MANAGER, msg.sender) on lrtConfig,
        // we need the lrtConfig (address(this)) to return true for hasRole.
        // We'll use a mock config that grants the role.
    }

    function testFuzz_property(address manager) public {
        // The manager must be a valid address that can be granted the MANAGER role
        vm.assume(manager != address(0) && manager != address(this));

        // Deploy a minimal mock config that grants MANAGER role to 'manager'
        MockLRTConfig config = new MockLRTConfig();
        config.grantRole(keccak256("MANAGER"), manager);

        // Update c's LRT config to the mock
        // We are the admin (DEFAULT_ADMIN_ROLE holder on the current lrtConfig which is address(this))
        c.updateLRTConfig(address(config));

        // Sanity: contract is not paused initially
        assertTrue(!c.paused(), "should not be paused initially");

        // Pause as the manager
        vm.prank(manager);
        c.pause();

        // After pausing, paused() must return true (reference behavior)
        // The mutant always returns false, so this assertion will fail for the mutant
        assertTrue(c.paused(), "paused() must return true after pause() is called by manager");
    }
}

