pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPause) public {
        // The reference contract's paused() must always agree with the actual _paused flag.
        // We drive the contract into a known state by pausing or not pausing,
        // then check that paused() reflects that state correctly.
        // The buggy version negates the flag, so it will fail when the contract is paused.

        // Initialize the contract first (it's needed for the access control modifiers)
        c.initialize(address(this));

        // Set up the access control roles for pausing
        // We are already admin (deployer), grant MANAGER role to ourselves for pause
        // First we need to set up lrtConfig properly - use the contract itself as config for testing
        // Actually, we can simply call pause/unpause if we have the right roles.
        // The contract uses onlyLRTManager for pause and onlyLRTAdmin for unpause.
        // Since we are the DEFAULT_ADMIN of the config (we deployed and initialized it),
        // we can grant ourselves MANAGER role.
        // But we don't have a real LRTConfig... We need to mock it or use a proper setup.
        // The simplest approach: since we control the lrtConfig address and it checks roles on that address,
        // we can deploy a minimal config that grants us roles, or we can use address(this) as config
        // and implement the interface minimally.
        // However, the contract uses lrtConfig for role checking via IAccessControl(lrtConfig).hasRole(...).
        // Since lrtConfig is set to the address passed in initialize(), and we passed address(this),
        // the pause/unpause functions will call IAccessControl(address(this)).hasRole(...).
        // We need to implement hasRole on this test contract. But that's complex.
        // Alternative: we can observe paused() without calling pause/unpause by using the fact
        // that the internal _paused starts as false after initialization.
        // But we need to test both states to catch the negation bug.
        // The bug is: when _paused is true, paused() returns false, and when _paused is false, paused() returns true.
        // So we need to test the case where _paused is true.
        // We can achieve this by calling _pause() if we have the roles, or by setting up the access control properly.

        // Let's set up a minimal LRTConfig that grants us roles.
        // We'll deploy a helper config.

        // Actually, we can inherit from C and expose a helper, but we can't modify C.
        // The test contract itself can implement IAccessControl if we set c.lrtConfig to address(this).
        // But we already did initialize(address(this)), so c.lrtConfig() returns address(this).
        // The role check uses: IAccessControl(lrtConfig).hasRole(role, msg.sender).
        // So we need this test contract to implement hasRole.
        // We can do that by making InvMutTest implement IAccessControl partially.
        // But the test contract is already Test, which doesn't have hasRole.
        // We can deploy a separate minimal config contract.

        // Let's deploy a MinimalConfig that always returns true for hasRole for any caller.
        MinimalConfig config = new MinimalConfig();
        c = new C(); // Re-deploy to avoid state contamination
        c.initialize(address(config));

        // Now when c checks hasRole, the config returns true for any caller.
        // We can now pause/unpause freely.

        if (shouldPause) {
            c.pause();
        } else {
            // Ensure it's unpaused (it starts unpaused, but if we test both we need to handle)
            // Actually, if we want to test the unpaused state, we just leave it as initialized.
            // But we might have previously paused it in this test run. Since shouldPause is fuzzed,
            // we need to ensure we start from a clean state each time. The setUp deploys a fresh C.
            // So we're good: if shouldPause is false, we don't pause.
        }

        // Now assert: paused() should match the state we set.
        bool actualPaused = c.paused();
        if (shouldPause) {
            assertTrue(actualPaused == true);
        } else {
            assertTrue(actualPaused == false);
        }
    }
}

contract MinimalConfig {
    // Minimal IAccessControl that allows everything
    function hasRole(bytes32, address) external pure returns (bool) {
        return true;
    }
    function getRoleAdmin(bytes32) external pure returns (bytes32) {
        return bytes32(0);
    }
    // Other required functions from ILRTConfig (we need to satisfy the interface for compile)
    function rsETH() external pure returns (address) { return address(0); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function isSupportedAsset(address) external pure returns (bool) { return false; }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32) external pure returns (address) { return address(0); }
    function getSupportedAssetList() external pure returns (address[] memory) { return new address[](0); }
    function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
