pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Initialize to have a valid config that supports pausing
        c.initialize(address(this));
        // Grant MANAGER role to self (simulate LRTConfig) so we can call pause()
        // This is needed because pause() is onlyLRTManager
        // We mock the role check by having the LRTConfig return true for hasRole
        // Since we cannot mock, we'll use the fact that the config is address(this) and hasRole is external.
        // We need a minimal config mock that returns true for hasRole(MANAGER, self).
        // The fuzzer provides the bool to decide whether to pause or not.
    }

    function testFuzz_property(bool shouldPause) public {
        // We need a way to set the internal _paused state without relying on the config role check.
        // The only way to toggle _paused is via pause()/unpause(), which require role checks.
        // To make the test practical, we use a mock LRTConfig that grants us the MANAGER role.
        // Since we can't import a mock, we deploy a minimal one inline.
        MockLRTConfig config = new MockLRTConfig();
        // Replace c's lrtConfig with the mock that gives us MANAGER role
        // updateLRTConfig is onlyLRTAdmin; our mock also grants DEFAULT_ADMIN_ROLE to self.
        c.updateLRTConfig(address(config));

        // Now we can pause if shouldPause is true
        if (shouldPause) {
            vm.prank(address(this));
            c.pause();
        }

        // The property: paused() should return true exactly when we paused the contract
        bool expectedPaused = shouldPause;
        bool actualPaused = c.paused();

        assertTrue(actualPaused == expectedPaused, "paused() must reflect the actual pause state");
    }
}

contract MockLRTConfig {
    bytes32 public constant MANAGER = keccak256("MANAGER");
    bytes32 public constant DEFAULT_ADMIN_ROLE = 0x00;

    function hasRole(bytes32 role, address account) external view returns (bool) {
        // Grant MANAGER and DEFAULT_ADMIN_ROLE to the test contract (msg.sender in setUp)
        // Since this is called by C, the account is msg.sender from C's perspective.
        // In pause(), C calls hasRole(MANAGER, msg.sender) where msg.sender is the pranked address.
        // So we just always return true for both roles for any account, which is safe for the test.
        return true;
    }

    function isSupportedAsset(address) external pure returns (bool) {
        return true;
    }

    function rsETH() external pure returns (address) {
        return address(0);
    }

    function depositLimitByAsset(address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function getContract(bytes32) external view returns (address) {
        return address(this);
    }
}

