contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address lrtConfigAddr, address manager) public {
        vm.assume(lrtConfigAddr != address(0));
        vm.assume(manager != address(0));
        vm.assume(lrtConfigAddr != manager);

        // Initialize C. We need a minimal LRTConfig-like contract that has roles setup,
        // but since paused() difference does NOT depend on the real LRTConfig (only on the role check
        // for pause), we can simply use an EOA. However, the initializer checks that lrtConfig is non-zero,
