        // The admin role is checked for initialize and possibly other functions, but we just initialized.
        // For pause, only manager is required. Manager now has the role.
        vm.prank(manager);
        c.pause();

        // Reference property: paused() must return true after pause.
        // Bug: paused() will return !_paused, i.e., false even though paused.
        assertTrue(c.paused());
    }
