import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newConfig) public {
        vm.assume(newConfig != address(0));
        // Deploy a mock config that implements the minimal interface to pass role checks
        MockLRTConfig mockConfig = new MockLRTConfig();
        // Initialize C with a zero address config to set up the initial state
        c.initialize(address(mockConfig));
        // Grant admin role to this test contract on the new mock config
        mockConfig.grantAdmin(address(this));
        // The update should change the config to newConfig
        c.updateLRTConfig(address(mockConfig));
        // After update, the admin on the new config should be able to call onlyLRTAdmin functions
        // getNodeDelegatorQueue is external and not restricted, but addNodeDelegatorContractToQueue is onlyLRTAdmin
        // We can test if the new admin has access by calling a restricted function
        // However, to avoid reverts that break the assertion, we use a try/catch on a view function that reads config
        // There is no public view that requires admin, but depositAsset requires asset to be supported.
        // Instead, we check that lrtConfig() returns the new address, which implies the role check would succeed.
        // But since the property says the bug breaks by not updating the state, any role check on the new config fails.
        // We assert that the admin of the new config can call a function that uses onlyLRTAdmin modifier.
        // Let's call addNodeDelegatorContractToQueue with a dummy array. If it doesn't revert, the config is updated.
        bool success;
        address[] memory dummy = new address[](1);
        dummy[0] = address(0x123);
        try c.addNodeDelegatorContractToQueue(dummy) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success);
    }
}

